use std::process::ExitCode;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params { count: u32, seed: u32, bins: u32, pad: u32 }
@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;
var<workgroup> local: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
    atomicStore(&local[lid.x], 0u);
    workgroupBarrier();
    let i = gid.x;
    if (i < p.count) {
        let a = ((i % 40000u) * 1597u + p.seed + 51749u) % 40000u;
        let b = (a * a + a * 37u + 11u) % 40009u;
        let c = (b * 613u + 7919u) % 40009u;
        let d = (c + (i / 40000u) * 7919u) % 40009u;
        let value = d % 1000u;
        atomicAdd(&local[value * p.bins / 1000u], 1u);
    }
    workgroupBarrier();
    let n = atomicLoad(&local[lid.x]);
    if (n > 0u) {
        atomicAdd(&hist[lid.x], n);
    }
}
"#;

fn run(path: &str) -> Result<String, String> {
    let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let nums: Vec<u32> = text
        .split_whitespace()
        .map(|t| t.parse::<u32>().map_err(|e| e.to_string()))
        .collect::<Result<_, _>>()?;
    let [count, seed, bins] = nums[..] else {
        return Err("expected: <count> <seed> <bins>".into());
    };
    if !(1..=256).contains(&bins) {
        return Err("bins out of range".into());
    }

    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| e.to_string())?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| e.to_string())?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&[count, seed, bins, 0u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let size = 256 * 4;
    let hist = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: hist.as_entire_binding() },
        ],
    });

    let mut encoder = device.create_command_encoder(&Default::default());
    encoder.clear_buffer(&hist, 0, None);
    if count > 0 {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(count.div_ceil(256), 1, 1);
    }
    encoder.copy_buffer_to_buffer(&hist, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    slice.map_async(wgpu::MapMode::Read, |r| r.expect("map failed"));
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    let counts: &[u32] = bytemuck::cast_slice(&data);

    let mut out = String::new();
    let mut total = 0u64;
    for (i, n) in counts.iter().take(bins as usize).enumerate() {
        out.push_str(&format!("BIN {i} {n}\n"));
        total += u64::from(*n);
    }
    if total != u64::from(count) {
        return Err(format!("internal error: counted {total}, expected {count}"));
    }
    out.push_str(&format!("TOTAL {count}\n"));
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: histogram <input-file>");
        return ExitCode::FAILURE;
    };
    match run(&path) {
        Ok(out) => {
            print!("{out}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
